sys_script_include.script:
var SigaUtils = Class.create();
SigaUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

  getBulletInfo: function() {
    var cbullet = this.getParameter('sysparm_bullet');

    var result = {
      alavanca: '',
      dimensao: '',
      dominio: ''
    };

    var gr = new GlideRecord('x_1488662_gal2_bullet');
    gr.addQuery('sys_id', cbullet);
    gr.query();

    if (gr.next()) {
      result.alavanca = gr.getValue('alavanca');   // replace with correct field name
      result.dimensao = gr.getValue('dimensao');
      result.dominio = gr.getValue('dominio');
    }

    return JSON.stringify(result); // 👈 Important: return as JSON string
  },

  type: 'SigaUtils'
});


